        let result = decode_abi_value(hex, "uint256");
        assert!(result.starts_with("0x"));
    }
}

//! # Access Control Mapping
//!
//! Analyzes smart contract source code to identify and map access control
//! patterns, privileged functions, ownership, and authorization mechanisms.
//!
//! ## Detected Patterns
//!
//! - **Ownable** - OpenZeppelin Ownable (onlyOwner modifier)
//! - **AccessControl** - Role-based access (OpenZeppelin AccessControl)
//! - **tx.origin** - Dangerous authorization via tx.origin
//! - **Custom modifiers** - Any modifier that gates function access
//! - **Renounced ownership** - renounceOwnership() calls detected
//! - **Multisig patterns** - Multiple signature requirements

use crate::contract::source::ContractSource;
use regex::Regex;
use serde::{Deserialize, Serialize};

/// Complete access control analysis for a contract.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AccessControlMap {
    /// Owner address pattern (if Ownable).
    pub ownership_pattern: Option<String>,
    /// Whether ownership has been renounced.
    pub has_renounced_ownership: bool,
    /// Whether role-based access control is used.
    pub has_role_based_access: bool,
    /// Whether tx.origin is used for authorization (dangerous).
    pub uses_tx_origin: bool,
    /// tx.origin usage locations.
    pub tx_origin_locations: Vec<SourceLocation>,
    /// Detected custom access modifiers.
    pub modifiers: Vec<AccessModifier>,
    /// Functions with access restrictions.
    pub privileged_functions: Vec<PrivilegedFunction>,
    /// Defined roles (AccessControl pattern).
    pub roles: Vec<String>,
    /// msg.sender vs tx.origin comparison.
    pub auth_analysis: AuthAnalysis,
}

/// A location in source code.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SourceLocation {
    /// File path or contract name.
    pub file: String,
    /// Approximate line number (0 if unknown).
    pub line: usize,
    /// The relevant code snippet.
    pub snippet: String,
}

/// An access control modifier.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AccessModifier {
    /// Modifier name (e.g., "onlyOwner", "onlyRole").
    pub name: String,
    /// What the modifier checks.
    pub check_type: ModifierCheckType,
    /// Number of functions using this modifier.
    pub usage_count: usize,
}

/// Type of access check performed by a modifier.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ModifierCheckType {
    /// Checks msg.sender == owner.
    OwnerOnly,
    /// Checks hasRole(role, msg.sender).
    RoleBased,
    /// Checks tx.origin (dangerous).
    TxOrigin,
    /// Custom/unknown check.
    Custom,
}

/// A function with access control restrictions.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PrivilegedFunction {
    /// Function name.
    pub name: String,
    /// Access modifier(s) applied.
    pub modifiers: Vec<String>,
    /// What this function can do (e.g., "mint tokens", "pause contract").
    pub capability: String,
    /// Risk level of this privileged operation.
    pub risk: PrivilegeRisk,
}

/// Risk level for a privileged operation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum PrivilegeRisk {
    /// Can drain funds or destroy contract.
    Critical,
    /// Can modify key parameters or pause.
    High,
    /// Can change configuration.
    Medium,
    /// Administrative but low risk.
    Low,
}

/// Authorization mechanism analysis.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuthAnalysis {
    /// Number of msg.sender checks found.
    pub msg_sender_checks: usize,
    /// Number of tx.origin checks found (should be 0 ideally).
    pub tx_origin_checks: usize,
    /// Whether require(tx.origin == msg.sender) pattern is used.
    pub has_origin_sender_comparison: bool,
    /// Summary of authorization approach.
    pub summary: String,
}

/// Analyze access control patterns in contract source code.
pub fn analyze_access_control(source: &ContractSource) -> AccessControlMap {
    let code = &source.source_code;

    let ownership_pattern = detect_ownership_pattern(code);
    let has_renounced_ownership = code.contains("renounceOwnership");
    let has_role_based_access =
        code.contains("AccessControl") || code.contains("hasRole") || code.contains("grantRole");
    let uses_tx_origin = code.contains("tx.origin");
    let tx_origin_locations = find_tx_origin_usage(code);
    let modifiers = detect_modifiers(code);
    let privileged_functions = detect_privileged_functions(code, &source.parsed_abi);
    let roles = detect_roles(code);
    let auth_analysis = analyze_auth_mechanisms(code);

    AccessControlMap {
        ownership_pattern,
        has_renounced_ownership,
        has_role_based_access,
        uses_tx_origin,
        tx_origin_locations,
        modifiers,
        privileged_functions,
        roles,
        auth_analysis,
    }
}

fn detect_ownership_pattern(code: &str) -> Option<String> {
    if code.contains("Ownable") {
        Some("OpenZeppelin Ownable".to_string())
    } else if code.contains("owner()") || code.contains("_owner") {
        Some("Custom owner pattern".to_string())
    } else if code.contains("AccessControl") {
        Some("Role-based (AccessControl)".to_string())
    } else {
        None
    }
}

fn find_tx_origin_usage(code: &str) -> Vec<SourceLocation> {
    let mut locations = Vec::new();
    for (line_num, line) in code.lines().enumerate() {
        if line.contains("tx.origin") {
            locations.push(SourceLocation {
                file: String::new(),
                line: line_num + 1,
                snippet: line.trim().to_string(),
            });
        }
    }
    locations
}

fn detect_modifiers(code: &str) -> Vec<AccessModifier> {
    let mut modifiers = Vec::new();

    // Match modifier definitions: `modifier name(...) {`
    let re = Regex::new(r"modifier\s+(\w+)").unwrap();
    for cap in re.captures_iter(code) {
        let name = cap[1].to_string();

        let check_type = if name.contains("onlyOwner") || name.contains("only_owner") {
            ModifierCheckType::OwnerOnly
        } else if name.contains("onlyRole")
            || name.contains("only_role")
            || name.contains("onlyAdmin")
        {
            ModifierCheckType::RoleBased
        } else {
            ModifierCheckType::Custom
        };

        // Count usage of this modifier in function declarations
        let usage_pattern = format!(r"\b{}\b", regex::escape(&name));
        let usage_re = Regex::new(&usage_pattern).unwrap();
        let usage_count = usage_re.find_iter(code).count().saturating_sub(1); // Subtract definition

        modifiers.push(AccessModifier {
            name,
            check_type,
            usage_count,
        });
    }

    // Detect onlyOwner even if defined in imported contract
    if code.contains("onlyOwner") && !modifiers.iter().any(|m| m.name == "onlyOwner") {
        let usage_re = Regex::new(r"\bonlyOwner\b").unwrap();
        let usage_count = usage_re.find_iter(code).count();
        modifiers.push(AccessModifier {
            name: "onlyOwner".to_string(),
            check_type: ModifierCheckType::OwnerOnly,
            usage_count,
        });
    }

    modifiers
}

fn detect_privileged_functions(
    code: &str,
    abi: &[crate::contract::source::AbiEntry],
) -> Vec<PrivilegedFunction> {
    let mut functions = Vec::new();

    // Detect common privileged function patterns
    let patterns: Vec<(&str, &str, PrivilegeRisk)> = vec![
        ("mint", "Mint/create new tokens", PrivilegeRisk::Critical),
        ("burn", "Burn/destroy tokens", PrivilegeRisk::High),
        ("pause", "Pause contract operations", PrivilegeRisk::High),
        (
            "unpause",
            "Unpause contract operations",
            PrivilegeRisk::High,
        ),
        ("setFee", "Modify fee parameters", PrivilegeRisk::Medium),
        ("setPrice", "Modify price parameters", PrivilegeRisk::Medium),
        (
            "withdraw",
            "Withdraw funds from contract",
            PrivilegeRisk::Critical,
        ),
        (
            "transferOwnership",
            "Transfer contract ownership",
            PrivilegeRisk::Critical,
        ),
        (
            "upgradeTo",
            "Upgrade contract implementation",
            PrivilegeRisk::Critical,
        ),
        ("selfdestruct", "Destroy contract", PrivilegeRisk::Critical),
        ("blacklist", "Blacklist addresses", PrivilegeRisk::High),
        ("whitelist", "Whitelist addresses", PrivilegeRisk::Medium),
        ("setOracle", "Change price oracle", PrivilegeRisk::Critical),
        ("setRouter", "Change DEX router", PrivilegeRisk::Critical),
    ];

    let fn_name_re = Regex::new(r"function\s+(\w+)").unwrap();

    for (pattern, capability, risk) in &patterns {
        // Check source for function + modifier combination
        let fn_re = Regex::new(&format!(
            r"function\s+\w*{}\w*\s*\([^)]*\)[^{{]*\b(onlyOwner|onlyRole|onlyAdmin|whenNotPaused)\b",
            regex::escape(pattern)
        ));
        if let Ok(re) = fn_re {
            for cap in re.captures_iter(code) {
                let full_match = cap.get(0).map_or("", |m| m.as_str());
                if let Some(fn_cap) = fn_name_re.captures(full_match) {
                    let fn_name = fn_cap[1].to_string();
                    let modifier = cap[1].to_string();
                    functions.push(PrivilegedFunction {
                        name: fn_name,
                        modifiers: vec![modifier],
                        capability: capability.to_string(),
                        risk: risk.clone(),
                    });
                }
            }
        }

        // Also check ABI for state-changing functions matching the pattern
        let pattern_lower = pattern.to_lowercase();
        for entry in abi {
            if entry.entry_type == "function"
                && entry.name.to_lowercase().contains(&pattern_lower)
                && entry.is_state_changing()
                && !functions.iter().any(|f| f.name == entry.name)
            {
                functions.push(PrivilegedFunction {
                    name: entry.name.clone(),
                    modifiers: vec!["(from ABI)".to_string()],
                    capability: capability.to_string(),
                    risk: risk.clone(),
                });
            }
        }
    }

    functions
}

fn detect_roles(code: &str) -> Vec<String> {
    let mut roles = Vec::new();

    // Match bytes32 constant role definitions
    // e.g., bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    let re = Regex::new(r#"(?:bytes32|constant)\s+.*?(\w+_ROLE)\s*="#).unwrap();
    for cap in re.captures_iter(code) {
        roles.push(cap[1].to_string());
    }

    // Common role patterns
    for role in &[
        "DEFAULT_ADMIN_ROLE",
        "MINTER_ROLE",
        "PAUSER_ROLE",
        "BURNER_ROLE",
        "UPGRADER_ROLE",
    ] {
        if code.contains(role) && !roles.contains(&role.to_string()) {
            roles.push(role.to_string());
        }
    }

    roles
}

fn analyze_auth_mechanisms(code: &str) -> AuthAnalysis {
    let msg_sender_re = Regex::new(r"msg\.sender").unwrap();
    let tx_origin_re = Regex::new(r"tx\.origin").unwrap();
    let origin_sender_re =
        Regex::new(r"(?:tx\.origin\s*==\s*msg\.sender|msg\.sender\s*==\s*tx\.origin)").unwrap();

    let msg_sender_checks = msg_sender_re.find_iter(code).count();
    let tx_origin_checks = tx_origin_re.find_iter(code).count();
    let has_origin_sender_comparison = origin_sender_re.is_match(code);

    let summary = if tx_origin_checks > 0 && !has_origin_sender_comparison {
        format!(
            "DANGER: Uses tx.origin ({} occurrence(s)) without msg.sender comparison. \
             This is vulnerable to phishing attacks via malicious contracts.",
            tx_origin_checks
        )
    } else if has_origin_sender_comparison {
        "Uses tx.origin == msg.sender comparison (anti-contract-call guard). \
         Less risky but blocks legitimate contract interactions."
            .to_string()
    } else if msg_sender_checks > 0 {
        format!(
            "Uses msg.sender for authorization ({} check(s)). This is the recommended approach.",
            msg_sender_checks
        )
    } else {
        "No explicit authorization checks detected.".to_string()
    };

    AuthAnalysis {
        msg_sender_checks,
        tx_origin_checks,
        has_origin_sender_comparison,
        summary,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::contract::source::ContractSource;

    fn make_source(code: &str) -> ContractSource {
        ContractSource {
            contract_name: "Test".to_string(),
            source_code: code.to_string(),
            abi: "[]".to_string(),
            compiler_version: "v0.8.19".to_string(),
            optimization_used: true,
            optimization_runs: 200,
            evm_version: "paris".to_string(),
            license_type: "MIT".to_string(),
            is_proxy: false,
            implementation_address: None,
            constructor_arguments: String::new(),
            library: String::new(),
            swarm_source: String::new(),
            parsed_abi: vec![],
        }
    }

    #[test]
    fn test_detect_ownable() {
        let src = make_source("contract Token is Ownable { function mint() onlyOwner {} }");
        let ac = analyze_access_control(&src);
        assert_eq!(
            ac.ownership_pattern,
            Some("OpenZeppelin Ownable".to_string())
        );
        assert!(!ac.has_renounced_ownership);
    }

    #[test]
    fn test_detect_renounced_ownership() {
        let src = make_source("contract Token { function renounceOwnership() {} }");
        let ac = analyze_access_control(&src);
        assert!(ac.has_renounced_ownership);
    }

    #[test]
    fn test_detect_tx_origin() {
        let src = make_source("require(tx.origin == owner, 'not owner');");
        let ac = analyze_access_control(&src);
        assert!(ac.uses_tx_origin);
        assert_eq!(ac.tx_origin_locations.len(), 1);
    }

    #[test]
    fn test_detect_roles() {
        let src = make_source(
            "bytes32 public constant MINTER_ROLE = keccak256('MINTER_ROLE');\n\
             bytes32 public constant PAUSER_ROLE = keccak256('PAUSER_ROLE');",
        );
        let ac = analyze_access_control(&src);
        assert!(ac.roles.contains(&"MINTER_ROLE".to_string()));
        assert!(ac.roles.contains(&"PAUSER_ROLE".to_string()));
    }

    #[test]
    fn test_detect_access_control() {
        let src = make_source(
            "import AccessControl; contract Token is AccessControl { \
             function mint() onlyRole(MINTER_ROLE) {} }",
        );
        let ac = analyze_access_control(&src);
        assert!(ac.has_role_based_access);
    }

    #[test]
    fn test_auth_analysis_safe() {
        let src = make_source("require(msg.sender == owner);");
        let ac = analyze_access_control(&src);
        assert_eq!(ac.auth_analysis.msg_sender_checks, 1);
        assert_eq!(ac.auth_analysis.tx_origin_checks, 0);
        assert!(ac.auth_analysis.summary.contains("recommended approach"));
    }

    #[test]
    fn test_auth_analysis_dangerous() {
        let src = make_source("require(tx.origin == owner);");
        let ac = analyze_access_control(&src);
        assert!(ac.auth_analysis.summary.contains("DANGER"));
    }

    #[test]
    fn test_detect_ownership_pattern_custom_owner() {
        let result = detect_ownership_pattern("function owner() public view returns (address) { return _owner; }");
        assert_eq!(result, Some("Custom owner pattern".to_string()));
    }

    #[test]
    fn test_detect_ownership_pattern_none() {
        let result = detect_ownership_pattern("contract SimpleToken { function transfer() {} }");
        assert_eq!(result, None);
    }

    #[test]
    fn test_detect_modifiers_custom() {
        let code = "modifier onlyValidator() { require(isValidator[msg.sender]); _; }\nfunction doThing() onlyValidator() {}";
        let modifiers = detect_modifiers(code);
        assert!(modifiers.iter().any(|m| m.name == "onlyValidator"));
        let validator_mod = modifiers.iter().find(|m| m.name == "onlyValidator").unwrap();
        assert!(matches!(validator_mod.check_type, ModifierCheckType::Custom));
    }

    #[test]
    fn test_detect_modifiers_role_based() {
        let code = "modifier onlyRole(bytes32 role) { _checkRole(role); _; }\nfunction mint() onlyRole(MINTER) {}";
        let modifiers = detect_modifiers(code);
        assert!(modifiers.iter().any(|m| m.name == "onlyRole"));
        let role_mod = modifiers.iter().find(|m| m.name == "onlyRole").unwrap();
        assert!(matches!(role_mod.check_type, ModifierCheckType::RoleBased));
    }

    #[test]
    fn test_detect_modifiers_admin() {
        let code = "modifier onlyAdmin() { require(msg.sender == admin); _; }";
        let modifiers = detect_modifiers(code);
        assert!(modifiers.iter().any(|m| m.name == "onlyAdmin"));
        let admin_mod = modifiers.iter().find(|m| m.name == "onlyAdmin").unwrap();
        assert!(matches!(admin_mod.check_type, ModifierCheckType::RoleBased));
    }

    #[test]
    fn test_detect_modifiers_imported_only_owner() {
        let code = "function mint() onlyOwner { tokens[msg.sender] += 1; }\nfunction burn() onlyOwner {}";
        let modifiers = detect_modifiers(code);
        assert!(modifiers.iter().any(|m| m.name == "onlyOwner"));
        let owner_mod = modifiers.iter().find(|m| m.name == "onlyOwner").unwrap();
        assert!(matches!(owner_mod.check_type, ModifierCheckType::OwnerOnly));
        assert!(owner_mod.usage_count >= 2);
    }

    #[test]
    fn test_detect_privileged_functions_with_abi() {
        use crate::contract::source::{AbiEntry, AbiParam};
        let code = "function mint(address to) onlyOwner { _mint(to); }";
        let abi = vec![
            AbiEntry {
                entry_type: "function".to_string(),
                name: "mint".to_string(),
                inputs: vec![AbiParam {
                    name: "to".to_string(),
                    param_type: "address".to_string(),
                    indexed: false,
                    components: vec![],
                }],
                outputs: vec![],
                state_mutability: "nonpayable".to_string(),
            },
            AbiEntry {
                entry_type: "function".to_string(),
                name: "pause".to_string(),
                inputs: vec![],
                outputs: vec![],
                state_mutability: "nonpayable".to_string(),
            },
        ];
        let fns = detect_privileged_functions(code, &abi);
        assert!(!fns.is_empty());
        assert!(fns.iter().any(|f| f.name == "mint"));
    }

    #[test]
    fn test_detect_privileged_functions_abi_only() {
        use crate::contract::source::{AbiEntry, AbiParam};
        let code = "contract Token {}";
        let abi = vec![AbiEntry {
            entry_type: "function".to_string(),
            name: "setFeeRecipient".to_string(),
            inputs: vec![AbiParam {
                name: "r".to_string(),
                param_type: "address".to_string(),
                indexed: false,
                components: vec![],
            }],
            outputs: vec![],
            state_mutability: "nonpayable".to_string(),
        }];
        let fns = detect_privileged_functions(code, &abi);
        assert!(fns.iter().any(|f| f.name == "setFeeRecipient"));
    }

    #[test]
    fn test_detect_roles_common_patterns() {
        let code = "contract Token {\n\
            bytes32 public constant UPGRADER_ROLE = keccak256('UPGRADER_ROLE');\n\
            DEFAULT_ADMIN_ROLE;\n\
            BURNER_ROLE;\n\
        }";
        let roles = detect_roles(code);
        assert!(roles.contains(&"UPGRADER_ROLE".to_string()));
        assert!(roles.contains(&"DEFAULT_ADMIN_ROLE".to_string()));
        assert!(roles.contains(&"BURNER_ROLE".to_string()));
    }

    #[test]
    fn test_analyze_auth_tx_origin_with_msg_sender() {
        let code = "require(tx.origin == msg.sender, 'no contracts');";
        let auth = analyze_auth_mechanisms(code);
        assert!(auth.has_origin_sender_comparison);
        assert!(auth.summary.contains("anti-contract-call"));
    }

    #[test]
    fn test_analyze_auth_no_checks() {
        let code = "contract Token { function transfer() {} }";
        let auth = analyze_auth_mechanisms(code);
        assert_eq!(auth.msg_sender_checks, 0);
        assert_eq!(auth.tx_origin_checks, 0);
        assert!(auth.summary.contains("No explicit authorization"));
    }

    #[test]
    fn test_find_tx_origin_usage_multiple() {
        let code = "require(tx.origin == owner);\nrequire(tx.origin != address(0));";
        let locations = find_tx_origin_usage(code);
        assert_eq!(locations.len(), 2);
        assert_eq!(locations[0].line, 1);
        assert_eq!(locations[1].line, 2);
    }

    #[test]
    fn test_privilege_risk_debug() {
        assert_eq!(format!("{:?}", PrivilegeRisk::Critical), "Critical");
        assert_eq!(format!("{:?}", PrivilegeRisk::High), "High");
        assert_eq!(format!("{:?}", PrivilegeRisk::Medium), "Medium");
        assert_eq!(format!("{:?}", PrivilegeRisk::Low), "Low");
    }

    #[test]
    fn test_modifier_check_type_debug() {
        assert_eq!(format!("{:?}", ModifierCheckType::OwnerOnly), "OwnerOnly");
        assert_eq!(format!("{:?}", ModifierCheckType::RoleBased), "RoleBased");
        assert_eq!(format!("{:?}", ModifierCheckType::Custom), "Custom");
    }
}

//! # DeFi Protocol Analysis
//!
//! Detects DeFi-specific patterns and risks in smart contract source code,
//! including oracle dependencies, flash loan risks, lending protocol patterns,
//! and DEX integration concerns.
//!
//! ## Detected Patterns
//!
//! - **Oracle usage** - Chainlink, Uniswap TWAP, Band Protocol
//! - **Flash loan vectors** - AAVE, dYdX flash loan callbacks
//! - **Lending patterns** - Borrow/lend, collateral, liquidation
//! - **DEX integration** - Uniswap, Sushiswap router calls, slippage checks
//! - **Staking/yield** - Staking, rewards, vesting patterns
//! - **Token standards** - ERC-20, ERC-721, ERC-1155 detection

use crate::contract::source::ContractSource;
use serde::{Deserialize, Serialize};

/// Complete DeFi analysis result.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DefiAnalysis {
    /// Protocol type classification.
    pub protocol_type: ProtocolType,
    /// Whether the contract depends on price oracles.
    pub has_oracle_dependency: bool,
    /// Oracle details.
    pub oracle_info: Vec<OracleInfo>,
    /// Whether flash loan attack vectors exist.
    pub has_flash_loan_risk: bool,
    /// Flash loan details.
    pub flash_loan_info: Vec<String>,
    /// DEX integration patterns found.
    pub dex_integrations: Vec<DexIntegration>,
    /// Lending/borrowing patterns.
    pub lending_patterns: Vec<String>,
    /// Token standard(s) implemented.
    pub token_standards: Vec<TokenStandard>,
    /// Staking/yield patterns.
    pub staking_patterns: Vec<String>,
    /// DeFi-specific risk factors.
    pub risk_factors: Vec<DefiRiskFactor>,
}

/// Classification of the DeFi protocol type.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ProtocolType {
    /// Token (ERC-20, ERC-721, etc.)
    Token,
    /// Decentralized exchange / AMM
    DEX,
    /// Lending protocol
    Lending,
    /// Yield farming / staking
    Yield,
    /// Governance
    Governance,
    /// Bridge
    Bridge,
    /// NFT marketplace
    NFTMarketplace,
    /// Generic / unclassified
    Other,
}

impl std::fmt::Display for ProtocolType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProtocolType::Token => write!(f, "Token"),
            ProtocolType::DEX => write!(f, "DEX/AMM"),
            ProtocolType::Lending => write!(f, "Lending"),
            ProtocolType::Yield => write!(f, "Yield/Staking"),
            ProtocolType::Governance => write!(f, "Governance"),
            ProtocolType::Bridge => write!(f, "Bridge"),
            ProtocolType::NFTMarketplace => write!(f, "NFT Marketplace"),
            ProtocolType::Other => write!(f, "Other"),
        }
    }
}

/// Oracle integration details.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OracleInfo {
    /// Oracle provider.
    pub provider: String,
    /// How the oracle is used.
    pub usage: String,
    /// Potential risks.
    pub risks: Vec<String>,
}

/// DEX integration details.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DexIntegration {
    /// DEX name/protocol.
    pub dex: String,
    /// Type of integration.
    pub integration_type: String,
    /// Whether slippage protection is present.
    pub has_slippage_protection: bool,
    /// Whether deadline protection is present.
    pub has_deadline_protection: bool,
}

/// Token standard detected.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum TokenStandard {
    ERC20,
    ERC721,
    ERC1155,
    ERC4626,
    Custom(String),
}

impl std::fmt::Display for TokenStandard {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            TokenStandard::ERC20 => write!(f, "ERC-20"),
            TokenStandard::ERC721 => write!(f, "ERC-721"),
            TokenStandard::ERC1155 => write!(f, "ERC-1155"),
            TokenStandard::ERC4626 => write!(f, "ERC-4626"),
            TokenStandard::Custom(name) => write!(f, "{}", name),
        }
    }
}

/// A DeFi-specific risk factor.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct DefiRiskFactor {
    /// Risk name.
    pub name: String,
    /// Description.
    pub description: String,
    /// Severity (1-10).
    pub severity: u8,
}

/// Analyze DeFi patterns in contract source code.
pub fn analyze_defi_patterns(source: &ContractSource) -> DefiAnalysis {
    let code = &source.source_code;

    let oracle_info = detect_oracles(code);
    let has_oracle_dependency = !oracle_info.is_empty();
    let flash_loan_info = detect_flash_loan_patterns(code);
    let has_flash_loan_risk = !flash_loan_info.is_empty();
    let dex_integrations = detect_dex_integrations(code);
    let lending_patterns = detect_lending_patterns(code);
    let token_standards = detect_token_standards(code, &source.parsed_abi);
    let staking_patterns = detect_staking_patterns(code);
    let protocol_type =
        classify_protocol(code, &token_standards, &dex_integrations, &lending_patterns);
    let risk_factors = assess_defi_risks(
        &oracle_info,
        &flash_loan_info,
        &dex_integrations,
        &lending_patterns,
    );

    DefiAnalysis {
        protocol_type,
        has_oracle_dependency,
        oracle_info,
        has_flash_loan_risk,
        flash_loan_info,
        dex_integrations,
        lending_patterns,
        token_standards,
        staking_patterns,
        risk_factors,
    }
}

fn detect_oracles(code: &str) -> Vec<OracleInfo> {
    let mut oracles = Vec::new();
    let code_lower = code.to_lowercase();

    // Chainlink
    if code_lower.contains("aggregatorv3interface")
        || code_lower.contains("latestrounddata")
        || code_lower.contains("chainlink")
        || code_lower.contains("pricefeed")
    {
        let mut risks = vec!["Stale price data if heartbeat check is missing".to_string()];

        // Check for proper staleness check
        if !code.contains("updatedAt") && !code.contains("answeredInRound") {
            risks.push("Missing staleness check on Chainlink price feed".to_string());
        }

        // Check for sequencer uptime feed (L2s)
        if !code_lower.contains("sequenceruptimefeed") {
            risks.push("Missing L2 sequencer uptime check (if deployed on L2)".to_string());
        }

        oracles.push(OracleInfo {
            provider: "Chainlink".to_string(),
            usage: "Price feed (AggregatorV3Interface)".to_string(),
            risks,
        });
    }

    // Uniswap TWAP
    if code_lower.contains("observe(")
        || code_lower.contains("twap")
        || code_lower.contains("oraclelibrary")
    {
        oracles.push(OracleInfo {
            provider: "Uniswap V3 TWAP".to_string(),
            usage: "Time-weighted average price oracle".to_string(),
            risks: vec![
                "TWAP can be manipulated with sustained capital over the observation window"
                    .to_string(),
                "Short TWAP windows are more susceptible to manipulation".to_string(),
            ],
        });
    }

    // Band Protocol
    if code_lower.contains("istdreference") || code_lower.contains("bandprotocol") {
        oracles.push(OracleInfo {
            provider: "Band Protocol".to_string(),
            usage: "External data oracle".to_string(),
            risks: vec!["Verify Band oracle reliability for the specific data feed".to_string()],
        });
    }

    // Generic getPrice / fetchPrice patterns
    if (code_lower.contains("getprice") || code_lower.contains("fetchprice")) && oracles.is_empty()
    {
        oracles.push(OracleInfo {
            provider: "Custom/Unknown".to_string(),
            usage: "Price retrieval function".to_string(),
            risks: vec!["Custom oracle — verify data source reliability".to_string()],
        });
    }

    oracles
}

fn detect_flash_loan_patterns(code: &str) -> Vec<String> {
    let mut patterns = Vec::new();
    let code_lower = code.to_lowercase();

    if code_lower.contains("flashloan") || code_lower.contains("flash_loan") {
        patterns.push("Flash loan function detected".to_string());
    }

    if code_lower.contains("executeflashloan")
        || code_lower.contains("onflashloan")
        || code_lower.contains("flashloansimple")
    {
        patterns.push("AAVE-style flash loan callback".to_string());
    }

    if code_lower.contains("callfunctionwithvalue") || code_lower.contains("flashborrowerfn") {
        patterns.push("dYdX-style flash loan integration".to_string());
    }

    if code_lower.contains("uniswapv2call") || code_lower.contains("uniswapv3flashcallback") {
        patterns.push("Uniswap flash swap callback".to_string());
    }

    // Check if the contract is flash-loan SAFE (validates balance changes)
    if !patterns.is_empty() && !code_lower.contains("balanceof") {
        patterns
            .push("WARNING: Flash loan callback without explicit balance validation".to_string());
    }

    patterns
}

fn detect_dex_integrations(code: &str) -> Vec<DexIntegration> {
    let mut integrations = Vec::new();
    let code_lower = code.to_lowercase();

    // Uniswap V2/V3 Router
    if code_lower.contains("iuniswapv2router") || code_lower.contains("swaprouter") {
        let has_slippage =
            code_lower.contains("amountoutmin") || code_lower.contains("amountinmax");
        let has_deadline =
            code_lower.contains("deadline") || code_lower.contains("block.timestamp");

        integrations.push(DexIntegration {
            dex: "Uniswap".to_string(),
            integration_type: "Swap router".to_string(),
            has_slippage_protection: has_slippage,
            has_deadline_protection: has_deadline,
        });
    }

    // SushiSwap
    if code_lower.contains("isushiswap") || code_lower.contains("sushirouter") {
        integrations.push(DexIntegration {
            dex: "SushiSwap".to_string(),
            integration_type: "Swap router".to_string(),
            has_slippage_protection: code_lower.contains("amountoutmin"),
            has_deadline_protection: code_lower.contains("deadline"),
        });
    }

    // Curve
    if code_lower.contains("icurve")
        || code_lower.contains("curvepool")
        || code_lower.contains("stableswap")
    {
        integrations.push(DexIntegration {
            dex: "Curve".to_string(),
            integration_type: "Stableswap pool".to_string(),
            has_slippage_protection: code_lower.contains("min_amount")
                || code_lower.contains("_min_dy"),
            has_deadline_protection: false,
        });
    }

    // Balancer
    if code_lower.contains("ibalancer")
        || code_lower.contains("ivault") && code_lower.contains("swap")
    {
        integrations.push(DexIntegration {
            dex: "Balancer".to_string(),
            integration_type: "Vault swap".to_string(),
            has_slippage_protection: code_lower.contains("limit"),
            has_deadline_protection: code_lower.contains("deadline"),
        });
    }

    integrations
}

fn detect_lending_patterns(code: &str) -> Vec<String> {
    let mut patterns = Vec::new();
    let code_lower = code.to_lowercase();

    if code_lower.contains("borrow") && code_lower.contains("repay") {
        patterns.push("Borrow/repay lending pattern".to_string());
    }

    if code_lower.contains("collateral") && code_lower.contains("liquidat") {
        patterns.push("Collateralized lending with liquidation".to_string());
    }

    if code_lower.contains("lendingpool") || code_lower.contains("comptroller") {
        patterns.push("Aave/Compound-style lending pool integration".to_string());
    }

    if code_lower.contains("healthfactor") || code_lower.contains("collateralratio") {
        patterns.push("Health factor / collateral ratio monitoring".to_string());
    }

    if code_lower.contains("interest") && code_lower.contains("rate") {
        patterns.push("Interest rate model".to_string());
    }

    patterns
}

fn detect_token_standards(
    code: &str,
    abi: &[crate::contract::source::AbiEntry],
) -> Vec<TokenStandard> {
    let mut standards = Vec::new();
    let code_lower = code.to_lowercase();

    // ERC-20 detection
    let has_erc20_functions = abi.iter().any(|e| {
        e.entry_type == "function"
            && (e.name == "transfer" || e.name == "approve" || e.name == "transferFrom")
    });
    if has_erc20_functions || code_lower.contains("erc20") || code_lower.contains("ierc20") {
        standards.push(TokenStandard::ERC20);
    }

    // ERC-721 detection
    let has_erc721 = abi.iter().any(|e| {
        e.entry_type == "function" && (e.name == "ownerOf" || e.name == "safeTransferFrom")
    });
    if has_erc721 || code_lower.contains("erc721") || code_lower.contains("ierc721") {
        standards.push(TokenStandard::ERC721);
    }

    // ERC-1155 detection
    if code_lower.contains("erc1155") || code_lower.contains("ierc1155") {
        standards.push(TokenStandard::ERC1155);
    }

    // ERC-4626 vault
    if code_lower.contains("erc4626")
        || (code_lower.contains("deposit") && code_lower.contains("shares"))
    {
        standards.push(TokenStandard::ERC4626);
    }

    standards
}

fn detect_staking_patterns(code: &str) -> Vec<String> {
    let mut patterns = Vec::new();
    let code_lower = code.to_lowercase();

    if code_lower.contains("stake") && code_lower.contains("unstake") {
        patterns.push("Stake/unstake mechanism".to_string());
    }

    if code_lower.contains("rewardpertoken") || code_lower.contains("earned") {
        patterns.push("Reward distribution (Synthetix-style)".to_string());
    }

    if code_lower.contains("vesting") || code_lower.contains("vestingschedule") {
        patterns.push("Token vesting schedule".to_string());
    }

    if code_lower.contains("timelock") || code_lower.contains("lockperiod") {
        patterns.push("Time-locked staking".to_string());
    }

    patterns
}

fn classify_protocol(
    code: &str,
    token_standards: &[TokenStandard],
    dex_integrations: &[DexIntegration],
    lending_patterns: &[String],
) -> ProtocolType {
    let code_lower = code.to_lowercase();

    if !lending_patterns.is_empty() {
        ProtocolType::Lending
    } else if !dex_integrations.is_empty()
        || code_lower.contains("addliquidity")
        || code_lower.contains("removeliquidity")
    {
        ProtocolType::DEX
    } else if code_lower.contains("governance")
        || code_lower.contains("propose") && code_lower.contains("vote")
    {
        ProtocolType::Governance
    } else if code_lower.contains("bridge") || code_lower.contains("crosschain") {
        ProtocolType::Bridge
    } else if token_standards
        .iter()
        .any(|s| matches!(s, TokenStandard::ERC721 | TokenStandard::ERC1155))
        && (code_lower.contains("marketplace") || code_lower.contains("auction"))
    {
        ProtocolType::NFTMarketplace
    } else if code_lower.contains("stake")
        || code_lower.contains("farm")
        || code_lower.contains("yield")
    {
        ProtocolType::Yield
    } else if !token_standards.is_empty() {
        ProtocolType::Token
    } else {
        ProtocolType::Other
    }
}

fn assess_defi_risks(
    oracle_info: &[OracleInfo],
    flash_loan_info: &[String],
    dex_integrations: &[DexIntegration],
    lending_patterns: &[String],
) -> Vec<DefiRiskFactor> {
    let mut risks = Vec::new();

    // Oracle risks
    for oracle in oracle_info {
        for risk in &oracle.risks {
            if risk.contains("Missing staleness") || risk.contains("Missing L2") {
                risks.push(DefiRiskFactor {
                    name: format!("{} oracle risk", oracle.provider),
                    description: risk.clone(),
                    severity: 7,
                });
            }
        }
    }

    // Flash loan risks
    if !flash_loan_info.is_empty() {
        risks.push(DefiRiskFactor {
            name: "Flash loan exposure".to_string(),
            description: "Contract interacts with flash loans. Ensure all state \
                changes are validated after flash loan execution."
                .to_string(),
            severity: 6,
        });
    }

    // DEX integration risks
    for dex in dex_integrations {
        if !dex.has_slippage_protection {
            risks.push(DefiRiskFactor {
                name: format!("{} missing slippage protection", dex.dex),
                description: "DEX swap without minimum output amount. Transaction \
                    can be sandwiched by MEV bots."
                    .to_string(),
                severity: 8,
            });
        }
        if !dex.has_deadline_protection {
            risks.push(DefiRiskFactor {
                name: format!("{} missing deadline", dex.dex),
                description: "DEX swap without deadline parameter. Transaction can be \
                    held in mempool indefinitely and executed at a bad price."
                    .to_string(),
                severity: 5,
            });
        }
    }

    // Lending risks
    if !lending_patterns.is_empty() && !lending_patterns.iter().any(|p| p.contains("liquidation")) {
        risks.push(DefiRiskFactor {
            name: "Lending without liquidation mechanism".to_string(),
            description: "Lending pattern detected without explicit liquidation handling. \
                Bad debt may accumulate without a liquidation pathway."
                .to_string(),
            severity: 7,
        });
    }

    risks
}

