//! Market client traits for fetching exchange data.
//!
//! These traits define the interface for fetching order books, tickers, and
//! recent trades. They are implemented by `ConfigurableExchangeClient` and
//! composed by the `ExchangeClient` facade.

use crate::error::Result;
use async_trait::async_trait;

use super::types::{Candle, OrderBook, Ticker, Trade};

/// Trait for clients that can fetch an order book snapshot.
#[async_trait]
pub trait OrderBookClient: Send + Sync {
    /// Fetch the current order book for the given pair symbol.
    async fn fetch_order_book(&self, pair_symbol: &str) -> Result<OrderBook>;
}

/// Trait for clients that can fetch a 24h ticker.
#[async_trait]
pub trait TickerClient: Send + Sync {
    /// Fetch the 24h ticker for the given pair symbol.
    async fn fetch_ticker(&self, pair_symbol: &str) -> Result<Ticker>;
}

/// Trait for clients that can fetch recent trades.
#[async_trait]
pub trait TradeHistoryClient: Send + Sync {
    /// Fetch the most recent trades for the given pair symbol.
    /// `limit` controls the maximum number of trades returned.
    async fn fetch_recent_trades(&self, pair_symbol: &str, limit: u32) -> Result<Vec<Trade>>;
}

/// Trait for clients that can fetch OHLC (candlestick / kline) data.
#[async_trait]
pub trait OhlcClient: Send + Sync {
    /// Fetch OHLC candlesticks for the given pair symbol.
    ///
    /// * `interval` — candle width (e.g., "1m", "5m", "15m", "1h", "4h", "1d").
    /// * `limit` — maximum number of candles to return.
    async fn fetch_ohlc(
        &self,
        pair_symbol: &str,
        interval: &str,
        limit: u32,
    ) -> Result<Vec<Candle>>;
}

//! Core market data types.
//!
//! Defines order book levels, full order books, execution estimates, and
//! the newer trade/ticker/snapshot types used by the exchange system.

// =============================================================================
// Order Book
// =============================================================================

/// A single price level in the order book.
#[derive(Debug, Clone, PartialEq)]
pub struct OrderBookLevel {
    /// Price (e.g., 1.0001)
    pub price: f64,
    /// Quantity in base asset (e.g., PUSD)
    pub quantity: f64,
}

impl OrderBookLevel {
    /// Value in quote asset (price × quantity, e.g., USDT).
    #[inline]
    pub fn value(&self) -> f64 {
        self.price * self.quantity
    }
}

/// Full order book snapshot with bids and asks.
#[derive(Debug, Clone)]
pub struct OrderBook {
    /// Trading pair label (e.g., "PUSD/USDT").
    pub pair: String,
    /// Bids sorted by price descending (best bid first).
    pub bids: Vec<OrderBookLevel>,
    /// Asks sorted by price ascending (best ask first).
    pub asks: Vec<OrderBookLevel>,
}

impl OrderBook {
    /// Best bid price, or None if empty.
    pub fn best_bid(&self) -> Option<f64> {
        self.bids.first().map(|l| l.price)
    }

    /// Best ask price, or None if empty.
    pub fn best_ask(&self) -> Option<f64> {
        self.asks.first().map(|l| l.price)
    }

    /// Mid price between best bid and ask.
    pub fn mid_price(&self) -> Option<f64> {
        match (self.best_bid(), self.best_ask()) {
            (Some(bid), Some(ask)) => Some((bid + ask) / 2.0),
            _ => None,
        }
    }

    /// Spread (ask - bid).
    pub fn spread(&self) -> Option<f64> {
        match (self.best_bid(), self.best_ask()) {
            (Some(bid), Some(ask)) => Some(ask - bid),
            _ => None,
        }
    }

    /// Total bid depth in quote terms (sum of price × quantity).
    pub fn bid_depth(&self) -> f64 {
        self.bids.iter().map(OrderBookLevel::value).sum()
    }

    /// Total ask depth in quote terms.
    pub fn ask_depth(&self) -> f64 {
        self.asks.iter().map(OrderBookLevel::value).sum()
    }

    /// Estimate slippage for buying a given USDT notional by walking the ask side.
    /// Returns (vwap, slippage_bps) if fillable, or None if insufficient liquidity.
    pub fn estimate_buy_execution(&self, notional_usdt: f64) -> Option<ExecutionEstimate> {
        let mid = self.mid_price()?;
        if mid <= 0.0 {
            return None;
        }
        let mut remaining = notional_usdt;
        let mut filled_value = 0.0;
        let mut filled_qty = 0.0;
        for level in &self.asks {
            let level_value = level.value();
            if remaining <= 0.0 {
                break;
            }
            let take_value = level_value.min(remaining);
            let take_qty = if level.price > 0.0 {
                take_value / level.price
            } else {
                0.0
            };
            filled_value += take_value;
            filled_qty += take_qty;
            remaining -= take_value;
        }
        let fillable = remaining <= 0.01;
        let vwap = if filled_qty > 0.0 {
            filled_value / filled_qty
        } else {
            mid
        };
        let slippage_bps = (vwap - mid) / mid * 10_000.0;
        Some(ExecutionEstimate {
            notional_usdt,
            side: ExecutionSide::Buy,
            vwap,
            slippage_bps,
            fillable,
        })
    }

    /// Estimate slippage for selling (hitting bids) a given USDT notional.
    pub fn estimate_sell_execution(&self, notional_usdt: f64) -> Option<ExecutionEstimate> {
        let mid = self.mid_price()?;
        if mid <= 0.0 {
            return None;
        }
        let mut remaining = notional_usdt;
        let mut filled_value = 0.0;
        let mut filled_qty = 0.0;
        for level in &self.bids {
            if remaining <= 0.0 {
                break;
            }
            let level_value = level.value();
            let take_value = level_value.min(remaining);
            let take_qty = if level.price > 0.0 {
                take_value / level.price
            } else {
                0.0
            };
            filled_value += take_value;
            filled_qty += take_qty;
            remaining -= take_value;
        }
        let fillable = remaining <= 0.01;
        let vwap = if filled_qty > 0.0 {
            filled_value / filled_qty
        } else {
            mid
        };
        let slippage_bps = (mid - vwap) / mid * 10_000.0;
        Some(ExecutionEstimate {
            notional_usdt,
            side: ExecutionSide::Sell,
            vwap,
            slippage_bps,
            fillable,
        })
    }
}

/// Side of execution (buy = hit asks, sell = hit bids).
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum ExecutionSide {
    Buy,
    Sell,
}

/// Result of execution simulation for a given notional size.
#[derive(Debug, Clone)]
pub struct ExecutionEstimate {
    pub notional_usdt: f64,
    pub side: ExecutionSide,
    pub vwap: f64,
    pub slippage_bps: f64,
    pub fillable: bool,
}

/// Outcome of a single health check.
#[derive(Debug, Clone, PartialEq)]
pub enum HealthCheck {
    Pass(String),
    Fail(String),
}

// =============================================================================
// Trade & Ticker Types
// =============================================================================

/// Side of a trade.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TradeSide {
    Buy,
    Sell,
}

/// A single trade from the recent trades endpoint.
#[derive(Debug, Clone)]
pub struct Trade {
    /// Trade price in quote currency.
    pub price: f64,
    /// Quantity in base currency.
    pub quantity: f64,
    /// Quote quantity (price × quantity), if provided.
    pub quote_quantity: Option<f64>,
    /// Timestamp in milliseconds since epoch.
    pub timestamp_ms: u64,
    /// Whether this was a buy or sell from the taker's perspective.
    pub side: TradeSide,
    /// Trade ID, if available.
    pub id: Option<String>,
}

/// 24-hour ticker / market stats.
#[derive(Debug, Clone)]
pub struct Ticker {
    /// Pair label (e.g., "BTC/USDT").
    pub pair: String,
    /// Last traded price.
    pub last_price: Option<f64>,
    /// 24h high.
    pub high_24h: Option<f64>,
    /// 24h low.
    pub low_24h: Option<f64>,
    /// 24h base volume.
    pub volume_24h: Option<f64>,
    /// 24h quote volume.
    pub quote_volume_24h: Option<f64>,
    /// Best bid (if included in ticker).
    pub best_bid: Option<f64>,
    /// Best ask (if included in ticker).
    pub best_ask: Option<f64>,
}

/// Aggregated market snapshot combining all available data for a pair.
#[derive(Debug, Clone)]
pub struct MarketSnapshot {
    pub order_book: Option<OrderBook>,
    pub ticker: Option<Ticker>,
    pub recent_trades: Option<Vec<Trade>>,
}

